int i = 123;
float f = 123.9f;
double d = 123.9;

// 判断表达式是否永真
printf("i == (int)(float)i: %d\n", i == (int)(float)i); // 假
printf("f == (float)(int)f: %d\n", f == (float)(int)f); // 假
printf("i == (int)(double)i: %d\n", i == (int)(double)i); // 真
printf("f == (float)(double)f: %d\n", f == (float)(double)f); // 真
printf("d == (float)d: %d\n", d == (float)d); // 假
printf("f == -(-f): %d\n", f == -(-f)); // 真
printf("(d + f) - d == f: %d\n", (d + f) - d == f); // 假

