float sum_array(int a[], unsigned len)
{
    int i, sum = 0;
    for (i = 0; i <= len - 1; i++)
        sum += a[i];
    return sum;
}

int copy_array(int *array, int count) {
    int i;
    int *myarray = (int *) malloc(count * sizeof (int));
    if (myarray == NULL)
        return -1;
    for (i = 0; i < count; i++)
        myarray[i] = array[i];
    return count;
}

#include <stdio.h>

int main() {
    int binary = 101101;
    int decimal = 0, i = 1;
    while (binary != 0) {
        decimal += (binary % 10) * i;
        binary /= 10;
        i *= 2;
    }
    printf("%d\n", decimal);
    return 0;
}

#include <stdio.h>

int main() {
    int decimal = 45;
    int binary[32], i = 0;
    while (decimal > 0) {
        binary[i++] = decimal % 2;
        decimal /= 2;
    }
    for (int j = i - 1; j >= 0; j--) {
        printf("%d", binary[j]);
    }
    printf("\n");
    return 0;
}
